let result = $input.first()?.json || {};
while (result && result.body) { result = result.body; }

// If prospect_profile was passed from Step 2, ensure it is preserved
const step2Data = $('2. Execute Prospect Research Module (Serper + Groq)').first()?.json || {};
const finalProspect = (result.prospect_profile && Object.keys(result.prospect_profile).length > 0)
  ? result.prospect_profile
  : (step2Data.prospect_profile || (step2Data.body && step2Data.body.prospect_profile) || {});

return [{
  json: {
    pipeline_status: 'COMPLETED_SUCCESSFULLY',
    orchestrated_at: new Date().toISOString(),
    tender: result.tender || step2Data.tender || { id: "AO-2026-TN-042", buyer: "Ministère de la Santé" },
    prospect_profile: finalProspect,
    rag_matching: result.rag_matching,
    proposal_draft: result.proposal_draft,
    pptx_deliverable: result.pptx_deliverable,
    dashboard_status: 'READY_FOR_COMMERCIAL_REVIEW'
  }
}];
